<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { app, gs, real, game, summon, summonAt, clearSummonAt, open, hands, setShared, setEnv, expand, populateNow, setSettings, selectToken, stage, possess, onState, gather, lookHere, revealRoom, toast, setMode } from '../session'
import { MONSTERS, monster } from '../rules/monsters'
import { crText, THRESHOLD, crowd } from '../rules/base'
import { sheet } from '../rules/hero'
import { THEMES, type ThemeId } from '../core/defs'
import { ROOM_TYPES, clearRoom, furnish } from '../core/gen/furnish'
import { makeRng, wordSeed } from '../core/rng'
import Script from './Script.vue'
import Calls from './Calls.vue'
import MonThumb from './MonThumb.vue'
import Portrait from './Portrait.vue'
import PopForm from './PopForm.vue'
const TABS = computed(() => [...(gs.value?.camp?.mod ? [['script', 'Script']] : []), ['scene', 'Scene'], ['dice', 'Dice'], ['bestiary', 'Beasts'], ['party', 'Party'], ['world', 'World'], ['hands', 'Powers']]); const G = computed(() => gs.value)
const pset = reactive({ ...gs.value!.set, fams: [...gs.value!.set.fams] }); watch(pset, () => setSettings({ ...pset, fams: [...pset.fams] }), { deep: true }); const q = ref(''), cr = ref('all'), fam = ref('all'), n = ref(1), hid = ref(false), boss = ref(false), ally = ref(false); const FAM = [...new Set(MONSTERS.flatMap(m => m.fams))].filter(f => !['boss', 'treasure'].includes(f)).sort(); const list = computed(() => MONSTERS.filter(m => (!q.value || (m.name + m.type).toLowerCase().includes(q.value.toLowerCase())) && (fam.value === 'all' || m.fams.includes(fam.value)) && (cr.value === 'all' || (cr.value === '0' ? m.cr < 1 : cr.value === '1' ? m.cr >= 1 && m.cr < 5 : cr.value === '5' ? m.cr >= 5 && m.cr < 11 : m.cr >= 11))).sort((a, b) => a.cr - b.cr || a.name.localeCompare(b.name))); const put = (id: string) => { summon(id, { n: n.value, hidden: hid.value, boss: boss.value, side: ally.value ? 'npc' : 'foe', at: summonAt ?? undefined }); clearSummonAt() }
const heroes = computed(() => Object.entries(G.value?.chars ?? {})); const diff = (xp: number) => { const L = heroes.value; if (!L.length) return ''; const t = [0, 1, 2, 3].map(i => L.reduce((a, [, h]) => a + THRESHOLD[h.level][i], 0)); const x = xp * crowd(1, L.length); return x >= t[3] ? 'deadly' : x >= t[2] ? 'hard' : x >= t[1] ? 'medium' : x >= t[0] ? 'easy' : 'trivial' }
const rid = computed(() => app.selRoom ?? app.room?.id ?? null); const room = computed(() => { void app.tokens; return rid.value !== null ? game.value?.world?.rooms.get(rid.value) ?? null : null }); const here = computed(() => { void G.value; return room.value ? Object.values(G.value?.mons ?? {}).filter(m => m.hp > 0 && stage?.room(m.id)?.id === room.value!.id) : [] }); const sel = computed(() => app.selToken ? app.tokens.find(t => t.id === app.selToken) : null), sm = computed(() => app.selToken ? G.value?.mons[app.selToken] : null), sh = computed(() => app.selToken ? G.value?.chars[app.selToken] : null); const setRoom = (p: any) => game.value!.run({ maps: { rooms: { set: [{ ...room.value!, ...p }], del: [] } } }, false); const refurnish = (type: string) => { const r = { ...room.value!, type }; game.value!.edit(() => { const w = game.value!.world!; w.rooms.set(r.id, r); clearRoom(w, r); furnish(w, r, makeRng(wordSeed())) }); toast('Refurnished.') }
const side = ref<'any' | 'n' | 'e' | 's' | 'w'>('any'), count = ref(5), theme = ref<ThemeId>('stone'), caves = ref(.2); const verbs = ['title', 'ask_check', 'ask_save', 'give_xp', 'give_gold', 'give_item', 'set_quest', 'spawn_npc', 'place_chest', 'place_trap', 'door', 'reveal_secret', 'build', 'grow_rooms', 'dig_deeper', 'teleport_party', 'effect', 'sound', 'pass_time', 'level_up', 'whisper', 'speak_as']; const verb = ref('ask_check'); const V = computed(() => { void G.value; return stage ? (dirVerbs().get(verb.value) ?? null) : null }); const args = ref<Record<string, any>>({}); import { dir } from '../session'; const dirVerbs = () => dir!.hands.verbs; const go = () => { const r = hands(verb.value, { ...args.value }); if (r.ok) toast(r.text) }; const nice = (s: string) => { const w = s.replace(/_/g, ' '); return w[0].toUpperCase() + w.slice(1) }; const pick = (m: string) => { q.value = ''; open('stat', m) }; const WEATHER = ['clear', 'rain', 'snow', 'fog']; const hr = (t: number) => `${String(Math.floor(t)).padStart(2, '0')}:${String(Math.floor(t % 1 * 60)).padStart(2, '0')}`; void setMode
</script>
<template><aside class="dock slate"><nav class="tabs"><button v-for="t in TABS" :key="t[0]" class="tab" :class="{ on: app.dock === t[0] }" @click="app.dock = t[0]">{{ t[1] }}</button></nav><div class="bd scroll">
  <Script v-if="app.dock === 'script'" /><Calls v-if="app.dock === 'dice'" />
  <template v-if="app.dock === 'scene'">
    <div v-if="sel" class="card"><div class="row"><Portrait :hero="sh" :mon="sm" :model="sm?.npc ? sel.m : undefined" :id="sel.id" :size="56" /><span class="grow"><b class="cut nm">{{ sel.name }}</b><span class="tiny muted">{{ sh ? `${sheet(sh).race.name} ${sheet(sh).cls.name.toLowerCase()} ${sh.level}` : sm ? `${monster(sm.ref)?.name}, CR ${crText(monster(sm.ref)?.cr ?? 0)}` : '' }}{{ sm?.boss ? ', boss' : '' }}{{ sel.hidden ? ', hidden' : '' }}</span><span class="hp" :class="{ hero: sel.side === 'hero' }"><i :style="{ width: sel.hp / Math.max(1, sel.max) * 100 + '%' }" /></span></span><b class="n2">{{ sel.hp }}<i>/{{ sel.max }}</i></b></div><div class="row wrap" style="margin-top:8px;gap:4px"><button class="btn sm" @click="open('hp', sel.id)">HP</button><button class="btn sm" @click="open('conds', sel.id)">Conditions</button><button class="btn sm" @click="sh ? open('sheet', sel.id) : open('stat', sm?.ref)">{{ sh ? 'Sheet' : 'Stats' }}</button><button v-if="sh" class="btn sm" @click="open('give', sel.id)">Give</button><button class="btn sm" @click="possess(app.possess === sel.id ? '' : sel.id)">{{ app.possess === sel.id ? 'Leave' : 'Possess' }}</button><button class="btn sm" @click="game!.run({ maps: { tokens: { set: [{ ...sel!, hidden: !sel!.hidden }], del: [] } } }, false); onState()">{{ sel.hidden ? 'Reveal' : 'Hide' }}</button><button v-if="sm" class="btn sm bad" @click="stage?.remove(sel.id)">Remove</button></div></div>
    <template v-if="room"><span class="cap">{{ room.name || 'Passage' }}</span><input class="field" :value="room.name" aria-label="Room name" placeholder="Name" @change="setRoom({ name: ($event.target as HTMLInputElement).value })"><textarea class="field" rows="2" :value="room.desc" aria-label="Description" placeholder="What they see" style="margin-top:5px" @change="setRoom({ desc: ($event.target as HTMLTextAreaElement).value })" /><textarea class="field" rows="2" :value="room.notes" aria-label="Notes" placeholder="Notes for you alone" style="margin-top:5px" @change="setRoom({ notes: ($event.target as HTMLTextAreaElement).value })" /><div class="row wrap" style="margin-top:6px;gap:4px"><button class="btn sm" @click="stage?.read(`${room.name}. ${room.desc}`)">Read aloud</button><button class="btn sm" @click="revealRoom(room.id)">Reveal</button><button class="btn sm" @click="populateNow({ only: room.id })">Populate</button><select class="field" style="width:auto;min-height:28px;padding:2px 6px" aria-label="Purpose" :value="room.type" @change="refurnish(($event.target as HTMLSelectElement).value)"><option v-for="t in ROOM_TYPES" :key="t" :value="t">{{ nice(t) }}</option></select></div><div v-if="here.length" class="mons"><button v-for="m in here" :key="m.id" :class="{ on: app.selToken === m.id }" @click="selectToken(m.id)"><MonThumb :id="m.ref" :size="30" /><span class="grow cut">{{ m.name }}</span><small>{{ m.state === 'asleep' ? 'asleep' : m.side === 'foe' ? '' : 'friendly' }}</small><span class="hp" style="width:44px"><i :style="{ width: m.hp / m.max * 100 + '%' }" /></span></button></div></template><p v-else class="muted">Choose a figure or a room. Right-click anything on the map for more.</p>
    <span class="cap">At the table</span><div class="row wrap" style="gap:4px"><button class="btn sm" :class="{ on: app.shared.paused }" @click="setShared({ paused: !app.shared.paused })">{{ app.shared.paused ? 'Resume' : 'Pause' }}</button><button class="btn sm" :class="{ on: app.shared.fog }" @click="setShared({ fog: !app.shared.fog })">Fog of war</button><button class="btn sm" :class="{ on: app.shared.grid }" @click="setShared({ grid: !app.shared.grid })">Grid</button><button class="btn sm" @click="lookHere">Look here</button><button class="btn sm" @click="gather">Gather heroes</button><button class="btn sm" :disabled="!!G?.combat" @click="hands('start_combat')">Fight</button></div><template v-if="G"><button class="opt" :class="{ on: G.set.autoMon }" @click="setSettings({ autoMon: !G.set.autoMon })"><i class="tick" /><span>Creatures fight by themselves</span></button><button class="opt" :class="{ on: G.set.autoNotice }" @click="setSettings({ autoNotice: !G.set.autoNotice })"><i class="tick" /><span>Creatures attack what they notice</span></button></template>
  </template>
  <template v-if="app.dock === 'bestiary'"><input v-model="q" class="field" placeholder="Find a creature" aria-label="Find a creature"><div class="row" style="margin:6px 0"><select v-model="fam" class="field" aria-label="Kind"><option value="all">Every kind</option><option v-for="f in FAM" :key="f" :value="f">{{ nice(f) }}</option></select><select v-model="cr" class="field" aria-label="Challenge"><option value="all">Any challenge</option><option value="0">Below 1</option><option value="1">1 to 4</option><option value="5">5 to 10</option><option value="11">11 and up</option></select></div><div class="row wrap" style="gap:4px;margin-bottom:6px"><button class="ib sm" aria-label="Fewer" @click="n = Math.max(1, n - 1)">−</button><b style="min-width:18px;text-align:center">{{ n }}</b><button class="ib sm" aria-label="More" @click="n = Math.min(12, n + 1)">+</button><button class="chip s" :class="{ on: hid }" @click="hid = !hid">Hidden</button><button class="chip s" :class="{ on: boss }" @click="boss = !boss">Boss</button><button class="chip s" :class="{ on: ally }" @click="ally = !ally">Friendly</button></div><div class="bl"><div v-for="m in list" :key="m.id" class="bm"><button class="th" v-tip="'Stat block'" @click="pick(m.id)"><MonThumb :id="m.id" :size="48" /></button><span class="grow"><b class="cut">{{ m.name }}</b><small>CR {{ crText(m.cr) }} · {{ m.hp }} HP · AC {{ m.ac }}<em :class="diff(m.xp)"> {{ diff(m.xp) }}</em></small></span><button class="btn sm" @click="put(m.id)">Summon</button></div></div></template>
  <template v-if="app.dock === 'party'"><p v-if="!heroes.length" class="muted">No heroes yet. Invite players: each brings a hero.</p><button class="btn primary wide" @click="open('invite')">Invite players</button><div v-for="[id, h] in heroes" :key="id" class="card" style="margin-top:8px"><div class="row"><Portrait :hero="h" :size="50" /><span class="grow"><b class="nm cut">{{ h.name }}</b><span class="tiny muted">{{ h.over?.race ?? sheet(h).race.name }} {{ h.over?.cls ?? sheet(h).cls.name.toLowerCase() + ' ' + h.level }}, AC {{ sheet(h).ac }}, sees {{ sheet(h).pp }}</span><span class="hp hero"><i :style="{ width: h.hp / sheet(h).max * 100 + '%' }" /></span></span><b class="n2">{{ h.hp }}<i>/{{ sheet(h).max }}</i></b></div><div class="row" style="margin-top:6px;gap:4px"><button class="btn sm" @click="open('sheet', id)">Sheet</button><button class="btn sm" @click="open('hp', id)">HP</button><button class="btn sm" @click="open('give', id)">Give</button><button class="btn sm" @click="open('amend', id)">Amend</button><button class="btn sm" :class="{ on: h.insp }" @click="real().chars[id].insp = !h.insp; onState()">Inspired</button><button v-if="h.dead" class="btn sm" @click="hands('revive', { hero: id })">Revive</button></div></div><span class="cap">For all</span><div class="row wrap" style="gap:4px"><button class="btn sm" @click="hands('rest', { kind: 'short' })">Short rest</button><button class="btn sm" @click="hands('rest', { kind: 'long' })">Long rest</button><button class="btn sm" @click="hands('heal', { who: 'party', amount: 999 })">Heal</button><button class="btn sm" @click="hands('level_up', { who: 'party' })">A level</button></div></template>
  <template v-if="app.dock === 'world' && G"><PopForm :set="pset" class="one" /><div class="row" style="margin:8px 0"><button class="btn primary grow" @click="populateNow({})">Fill empty rooms</button><button class="btn" @click="populateNow({ clear: true })">Start over</button></div><p class="tiny muted">{{ Object.values(G.mons).filter(m => m.hp > 0 && m.side === 'foe').length }} creatures, {{ Object.values(G.mons).filter(m => m.boss && m.hp > 0).length }} bosses, {{ Object.keys(G.traps).length }} traps, {{ Object.keys(G.locks).length }} locks.</p><span class="cap">Grow the map</span><div class="chips"><button v-for="s in ([['any', 'Anywhere'], ['n', 'North'], ['e', 'East'], ['s', 'South'], ['w', 'West']] as const)" :key="s[0]" class="chip s" :class="{ on: side === s[0] }" @click="side = s[0]">{{ s[1] }}</button></div><label class="lab">Rooms: {{ count }}</label><input v-model.number="count" type="range" min="1" max="15" aria-label="Rooms"><select v-model="theme" class="field" aria-label="Theme"><option v-for="t in THEMES" :key="t.id" :value="t.id">{{ t.name }}</option></select><label class="lab">Caves: {{ Math.round(caves * 100) }}%</label><input v-model.number="caves" type="range" min="0" max="1" step=".1" aria-label="Caves"><div class="row"><button class="btn grow" @click="expand({ side, count, theme, caves })">Grow</button><button class="btn grow" @click="expand({ side, count, theme, caves, deeper: true })">Dig deeper</button></div><span class="cap">Sky</span><label class="lab">{{ hr(app.env.time) }}</label><input type="range" min="0" max="24" step=".25" :value="app.env.time" aria-label="Hour" @change="setEnv({ time: +($event.target as HTMLInputElement).value })"><div class="chips"><button v-for="w in WEATHER" :key="w" class="chip s" :class="{ on: app.env.weather === w }" @click="setEnv({ weather: w })">{{ nice(w) }}</button></div><label class="lab">Haze</label><input type="range" min="0" max="2.5" step=".1" :value="app.env.fogMul" aria-label="Haze" @change="setEnv({ fogMul: +($event.target as HTMLInputElement).value })"></template>
  <template v-if="app.dock === 'hands'"><p class="muted tiny">Every power the AI Dungeon Master has is yours too.</p><select v-model="verb" class="field" aria-label="Power" @change="args = {}"><option v-for="v in verbs" :key="v" :value="v">{{ nice(v) }}</option></select><template v-if="V"><p class="tiny muted" style="margin:6px 0 0">{{ V.does }}</p><template v-for="(d, k) in V.args" :key="k"><label class="lab">{{ nice(k as string) }}{{ d.need ? '' : ', optional' }}</label><select v-if="d.opts" v-model="args[k]" class="field" :aria-label="k as string"><option v-for="o in d.opts" :key="o" :value="o">{{ nice(o) }}</option></select><input v-else v-model="args[k]" class="field" :type="d.t === 'number' ? 'number' : 'text'" :placeholder="d.d" :aria-label="k as string"></template><button class="btn primary wide" style="margin-top:10px" @click="go">{{ nice(verb) }}</button></template></template>
</div></aside></template>
<style scoped>.dock{display:flex;flex-direction:column;min-height:0;pointer-events:auto}.tabs .tab{flex:1;justify-content:center;padding:12px 2px 9px;font-size:16px}.bd{flex:1;min-height:0;padding:14px 16px 20px}.card{padding:0 0 10px;border-bottom:1px solid var(--line2);margin-bottom:12px}.nm{display:block;font:700 21px/1.05 var(--serif)}.n2{font:800 29px/1 var(--serif)}.n2 i{font-style:normal;font-size:18px;color:var(--tx2)}.card .hp{display:block;margin-top:5px}.tiny{display:block}.mons{margin-top:8px;display:grid}.mons button{display:flex;gap:9px;align-items:center;padding:3px 0;border-bottom:1px solid var(--line)}.mons button:hover{background:var(--navy2)}.mons .on{background:var(--spot)!important;color:var(--on-spot)}.mons small{color:var(--tx3)}.bl{display:grid}.bm{display:flex;align-items:center;gap:10px;border-bottom:1px solid var(--line);content-visibility:auto;contain-intrinsic-size:54px}.bm:hover{background:var(--navy2)}.bm b{display:block;font:700 18px/1.1 var(--serif)}.bm small{color:var(--tx2);font-size:15px}.bm em{font-style:normal}.deadly{color:#ff8f7c}.hard{color:#f0b14e}.medium{color:#e3d777}.easy,.trivial{color:#7fd0a0}.one :deep(.pf){grid-template-columns:1fr}.one{grid-template-columns:1fr!important}</style>
